+  __aicore__ inline void CastToFloat(const LocalTensor<float>& dst, const LocalTensor<D_IN>& src, uint32_t count) {
+    Cast(dst, src, RoundMode::CAST_NONE, count);
+    PipeBarrier<PIPE_V>();
+  }
