+  __aicore__ inline void CastToBf16(const LocalTensor<D_IN>& dst, const LocalTensor<float>& src, uint32_t count) {
+    Cast(dst, src, RoundMode::CAST_RINT, count);
+    PipeBarrier<PIPE_V>();
+  }
