+      CastRowToFp32CounterNoSetMask(row_, in);
+      PipeBarrier<PIPE_V>();
+      MulAddRowByBrcBlock(acc_, row_, broadcast_[n * FLOAT_BLOCK_ELEMS], outputCount_,
